const body = $input.first()?.json?.body || $input.first()?.json || {};
const text = (body.text || body.message || '').toString();
const priority = (body.priority || 'normal').toString();

if (!text.trim()) {
  return [{ json: { error: 'no text supplied' } }];
}

// Compose with priority emoji.
const prefix = priority === 'high' ? '🚨 ' : (priority === 'low' ? '💭 ' : '');
const out = `${prefix}${text.slice(0, 4000)}`;
return [{ json: { chat_id: '{{telegram_chat_id}}', text: out, parse_mode: 'Markdown' } }];
